// Package apperrors contains public application error codes.
package apperrors

import "github.com/dronm/webapp"

const (
	ClientNotFound      = "2000"
	CodeSessionRequired = "session_required"
)

// SessionRequired is the application error expected by session-protected
// services generated by codegen.
func SessionRequired() error {
	return webapp.Unauthorized("active session required", map[string]any{
		"code": CodeSessionRequired,
	})
}
